-- Gate-pass / dispatch PROJECTION configs were never captured in a migration —
-- they were hand-inserted into a dev DB via the workflow designer, so no deployed
-- box (Sunraja included) ever received them. Result: a gate-pass transition created
-- the workflow instance but the projection listener found no config and wrote no
-- gate_pass row → the Dispatch list came back empty.
--
-- Ship them as PRODUCT DEFAULTS at tenant_id = -1. Paired with WorkflowProjectionListener
-- / DispatchToleranceListener now resolving `tenant_id IN (?, -1)`, this makes every
-- tenant (current and future) project correctly with zero per-customer seeding.
-- Idempotent: the scoped DELETE lets the M0PageSchemaInitialiser reapply hook re-run it.

DELETE FROM m0_workflow_projection
 WHERE tenant_id = -1
   AND workflow_code IN ('M10.FGLoading','M10.PackLoading','M10.PackUnload',
                         'M10.ReturnStockIn','M10.TankerInbound','M10.TankerOutbound');

